using System;
using System.Collections.Generic;
using Outbreak.Core;
using Outbreak.Contracts;
using Outbreak.Persistence;
public static partial class Program
{
    private static World SeekConsumer(Func<World,bool> goal,int max=2200){World world=EncounterScenarios.ConsumerVehicleShoppingTest();for(int t=0;t<max && !goal(world);t++)world.Step();Require(goal(world),"Consumer preview never reached requested stage.");return world;}
    private static void CheckConsumerVehicleCases()
    {
        Check("Vehicle shoppers physically haul multiple carts and conserve food through home unloading",()=>{
            World world=EncounterScenarios.ConsumerVehicleShoppingTest();int initial=world.FoodSupplies().RemainingMeals,eaten=0,loads=0,unloads=0;bool boarded=false,homeDrive=false,cartSeen=false;
            for(int t=0;t<2200 && ShopperHomeFood(world)<12;t++){
                var before=world.VehicleAtIndex(0);var human=world.ActorAt(0);world.Step();var car=world.VehicleAtIndex(0);var actor=world.ActorAt(0);if(actor.hunger<human.hunger)eaten++;
                Require(world.FoodSupplies().RemainingMeals+eaten==initial,"Consumer cart or vehicle transfer created or lost food.");Require(actor.carriedFood<=HungerRules.CarryLimit && car.handFood<=6 && car.cargoFood<=48 && car.handFood+car.cargoFood<=48,"Consumer inventory exceeded its compartment limits.");
                if(before.consumerPhase==ConsumerVehiclePhase.LoadingCar && car.cargoFood>before.cargoFood){loads++;Require(Math.Abs(actor.x-car.x)+Math.Abs(actor.y-car.y)==1,"Vehicle was loaded remotely.");}
                if(before.consumerPhase==ConsumerVehiclePhase.UnloadingHome && car.handFood<before.handFood)unloads++;
                if(ShopperHomeFood(world)>0)Require(car.consumerPhase!=ConsumerVehiclePhase.Shopping,"Home food appeared while shopping remotely.");boarded|=car.driverAboard;homeDrive|=car.consumerPhase==ConsumerVehiclePhase.DrivingHome;cartSeen|=car.handFood>0 && !car.driverAboard;
                if(car.driverAboard)Require(world.ActorInVehicle(0) && actor.x==car.x && actor.y==car.y && car.handFood==0,"Seated shopper and cargo diverged.");
            }
            Require(boarded && homeDrive && cartSeen && loads>=2 && unloads>=2 && ShopperHomeFood(world)==12 && world.VehicleAtIndex(0).consumerPhase==ConsumerVehiclePhase.None,"Consumer failed multiple loading/unloading trips or its twelve-meal home delivery.");
        });
        Check("Consumer cargo carries more than the courier load through repeated six-meal cart trips",()=>{
            var saved=EncounterScenarios.ConsumerVehicleShoppingTest().Capture();int home=saved.actors[0].assignedHouseId,store=saved.actors[0].familiarStoreId;World layout=World.Restore(saved);foreach(var box in saved.map.storageBoxes)if(layout.HouseAt(box.x,box.y)==home){box.capacity=48;box.foodReserve=30;}foreach(var shelf in saved.map.shelves)if(layout.HouseAt(shelf.x,shelf.y)==store)shelf.food=60;World world=World.Restore(saved);int peak=0;bool returned=false;for(int t=0;t<3600;t++){world.Step();var car=world.VehicleAtIndex(0);peak=Math.Max(peak,car.cargoFood);returned|=car.consumerPhase==ConsumerVehiclePhase.DrivingHome;if(returned && car.consumerPhase==ConsumerVehiclePhase.None)break;}Require(peak>=30 && ShopperHomeFood(world)>24,"Larger cargo did not deliver a load above the existing courier capacity.");
        });
        Check("Consumer shopping phases resume exactly after saved driving cart loading and unloading",()=>{
            World world=EncounterScenarios.ConsumerVehicleShoppingTest();var seen=new HashSet<ConsumerVehiclePhase>();for(int t=0;t<2000;t++){world.Step();var phase=world.VehicleAtIndex(0).consumerPhase;if(!seen.Add(phase))continue;World copy=Documents.ParseSave(State(world));Run(world,13);Run(copy,13);t+=13;Require(State(world)==State(copy),"Consumer vehicle phase diverged after save.");}
            Require(seen.Contains(ConsumerVehiclePhase.Shopping) && seen.Contains(ConsumerVehiclePhase.LoadingCar) && seen.Contains(ConsumerVehiclePhase.DrivingToStore) && seen.Contains(ConsumerVehiclePhase.DrivingHome) && seen.Contains(ConsumerVehiclePhase.UnloadingHome),"Consumer save check missed a physical trip phase.");
        });
        Check("Paused shopper keeps finite cargo occupant and reservation without manual steering",()=>{
            World world=SeekConsumer(w=>w.VehicleAtIndex(0).driverAboard && w.VehicleAtIndex(0).cargoFood>0);var before=world.VehicleAtIndex(0);Require(world.TryStopVehicle(0),"Shopper could not pause.");Run(world,20);var car=world.VehicleAtIndex(0);Require(car.x==before.x && car.y==before.y && car.driverAboard && car.deliveriesPaused,"Paused shopper kept driving.");string paused=State(world);Require(!world.TryUnassignVehicleCourier(0) && !world.TrySetVehicleDestination(0,car.x,car.y) && State(world)==paused,"Paused shopping accepted a conflicting command.");World copy=Documents.ParseSave(paused);Require(world.TryResumeVehicleCourier(0) && copy.TryResumeVehicleCourier(0),"Paused consumer could not resume.");Run(world,150);Run(copy,150);Require(State(world)==State(copy),"Resumed shopper diverged.");
        });
        Check("A reduced home reserve keeps excess in the vehicle and later uses it without another purchase",()=>{
            World world=SeekConsumer(w=>w.VehicleAtIndex(0).consumerPhase==ConsumerVehiclePhase.DrivingHome);int source=world.VehicleAtIndex(0).sourceBox-1;Require(world.TrySetStorageFoodReserve(source%world.Width,source/world.Width,0),"Could not reduce home reserve.");for(int t=0;t<1700 && world.VehicleAtIndex(0).consumerPhase!=ConsumerVehiclePhase.None;t++)world.Step();Require(world.VehicleAtIndex(0).consumerPhase==ConsumerVehiclePhase.None && world.VehicleAtIndex(0).cargoFood>0 && world.VehicleAtIndex(0).handFood==0 && ShopperHomeFood(world)==0,"Excess groceries vanished or overfilled home.");world=Documents.ParseSave(State(world));int shelfFood=world.FoodSupplies().ShelfMeals;Require(world.TrySetStorageFoodReserve(source%world.Width,source/world.Width,6),"Could not restore reserve.");for(int t=0;t<800 && ShopperHomeFood(world)==0;t++)world.Step();Require(ShopperHomeFood(world)>0 && world.FoodSupplies().ShelfMeals==shelfFood,"Retained vehicle food required a new store pickup.");
        });
        Check("An empty shop cannot fabricate cart contents or replenish the home",()=>{
            var saved=EncounterScenarios.ConsumerVehicleShoppingTest().Capture();foreach(var shelf in saved.map.shelves)shelf.food=0;World world=World.Restore(saved);bool visited=false,returned=false;for(int t=0;t<5000;t++){world.Step();var car=world.VehicleAtIndex(0);visited|=car.consumerPhase==ConsumerVehiclePhase.Shopping;returned|=visited && car.consumerPhase==ConsumerVehiclePhase.None;Require(car.handFood==0 && car.cargoFood==0 && ShopperHomeFood(world)==0,"Empty shop fabricated groceries.");if(returned)break;}Require(visited && returned,"Empty shop did not return its shopper safely.");
        });
        Check("A vehicle shopper tries a farther familiar shop after the nearest shelf is exhausted",()=>{
            World initial=EncounterScenarios.ConsumerVehicleShoppingTest();var saved=initial.Capture();int near=saved.actors[0].familiarStoreId;foreach(var shelf in saved.map.shelves)shelf.food=initial.HouseAt(shelf.x,shelf.y)==near?0:18;World world=World.Restore(saved);var visited=new HashSet<int>();for(int t=0;t<5000;t++){world.Step();var car=world.VehicleAtIndex(0);if(car.consumerPhase==ConsumerVehiclePhase.Shopping)visited.Add(world.HouseAt((car.targetBox-1)%world.Width,(car.targetBox-1)/world.Width));if(visited.Count>=2 && ShopperHomeFood(world)>0)break;}Require(visited.Count>=2 && ShopperHomeFood(world)>0,"Shopper kept cycling to the empty nearest store instead of loading at the farther known shop.");
        });
        Check("An incapacitated shopper leaves a finite cart for an assigned household replacement",()=>{
            World world=SeekConsumer(w=>w.VehicleAtIndex(0).consumerPhase==ConsumerVehiclePhase.LoadingCar && w.VehicleAtIndex(0).handFood>0 && w.HouseAt(w.ActorAt(0).x,w.ActorAt(0).y)==0 && w.Tick%HungerRules.GainTicks==HungerRules.GainTicks-1);var saved=world.Capture();int home=saved.actors[0].assignedHouseId;saved.actors[0].health=1;saved.actors[0].hunger=100;saved.actors[0].energySpent=100;saved.actors[0].carriedFood=0;int food=saved.vehicles[0].handFood;world=World.Restore(saved);world.Step();var dropped=world.VehicleAtIndex(0);Require(dropped.shipmentDropped && dropped.handFood==food && dropped.deliveriesPaused && dropped.consumerPhase==ConsumerVehiclePhase.RecoverCart,"Incapacitated shopper lost cart groceries.");world=Documents.ParseSave(State(world));int replacement=world.Count,id;bool placed=false;for(int y=0;y<world.Height && !placed;y++)for(int x=0;x<world.Width && !placed;x++)if(world.HouseAt(x,y)==home)placed=world.TrySpawn(Species.Human,x,y,out id);Require(placed,"No replacement spawn available.");var replacementActor=world.ActorAt(replacement);Require(world.TryAssignHouse(replacement,replacementActor.x,replacementActor.y) && world.TryAssignVehicleShopper(0,replacement),"Household replacement could not claim abandoned shopping vehicle.");world.TryFamiliarizeResidentsWithShops();for(int t=0;t<3000 && world.VehicleAtIndex(0).consumerPhase!=ConsumerVehiclePhase.None;t++)world.Step();Require(world.VehicleAtIndex(0).consumerPhase==ConsumerVehiclePhase.None && !world.VehicleAtIndex(0).shipmentDropped && world.VehicleAtIndex(0).handFood==0 && HouseholdFood(world,home)>0,"Replacement failed to recover cart and return real supplies.");
        });
        Check("Consumer vehicle capacity role clock and older-rule validation reject corrupt saves",()=>{
            Action<Action<SaveDocument>> bad=change=>{World world=SeekConsumer(w=>w.VehicleAtIndex(0).driverAboard && w.VehicleAtIndex(0).cargoFood>0);var saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.rulesVersion=EncounterRules.ShoppingContinuityVersion);bad(s=>s.vehicles[0].cargoFood=49);bad(s=>s.vehicles[0].handFood=7);bad(s=>s.vehicles[0].purchaseGoal=49);bad(s=>s.vehicles[0].consumerDriver=false);bad(s=>s.vehicles[0].consumerPhase=(ConsumerVehiclePhase)99);bad(s=>s.vehicles[0].driverAboard=false);bad(s=>s.actors[0].x++);bad(s=>s.vehicles[0].orderId=1);bad(s=>s.vehicles[0].exitAtTick=s.tick+100);bad(s=>s.vehicles[0].targetBox=1);
            var old=EncounterScenarios.LargeCityShoppingTest().Capture();old.rulesVersion=EncounterRules.ShoppingContinuityVersion;old.actors[0].additionalFamiliarStores=null;World legacy=World.Restore(old);Require(!legacy.ConsumerVehiclesEnabled,"Rules 97 silently enabled consumer vehicles.");
        });
    }
    private static int HouseholdFood(World world,int home){int food=0;foreach(var box in world.StorageBoxSites())if(world.HouseAt(box.x,box.y)==home)food+=StorageRules.Count(box,InventoryItem.Food);return food;}
}
